import 'package:flutter/material.dart';import 'package:pos_app/core/app_services.dart';import 'package:pos_app/features/backup/data/local_backup_provider.dart';import 'package:pos_app/shared/presentation/app_navigation_drawer.dart';class BackupScreen extends StatelessWidget{const BackupScreen({super.key});@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Respaldos')),drawer:const AppNavigationDrawer(),body:Center(child:FilledButton.icon(onPressed:()async{final path=await LocalBackupProvider(appDatabase).createBackup();if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Respaldo: $path')));},icon:const Icon(Icons.backup),label:const Text('Crear respaldo local'))));}
